                    if (categoryValue.include && typeof categoryValue.include === "object") {
                        includeRows = includeRows.concat(rowsFromFeatureMap(categoryValue.include, "include", config, { unsupportedFeatureKeys }));
                    }
                    if (categoryValue.exclude && typeof categoryValue.exclude === "object") {
                        excludeRows = excludeRows.concat(rowsFromFeatureMap(categoryValue.exclude, "exclude", config, { unsupportedFeatureKeys }));
                    }
                    // also allow a flat feature map per category for include-side categories
                    const recognized = new Set(["include", "exclude"]);
                    const flatEntries = Object.fromEntries(
                        Object.entries(categoryValue).filter(([key]) => !recognized.has(String(key || "").trim().toLowerCase())),
                    );
                    if (Object.keys(flatEntries).length > 0) {
                        includeRows = includeRows.concat(rowsFromFeatureMap(flatEntries, "include", config, { unsupportedFeatureKeys }));
