    function prefillRowsFromCanonicalTargeting(expression, config, groupId) {
        const normalized = String(expression || "").trim();
        if (!normalized) {
            return [];
        }
        const filtersByFeature = new Map(
            effectiveGroupFilters(config, groupId)
                .map((filterDef) => [String(filterDef?.targetingFeatureKey || "").trim(), filterDef])
                .filter(([featureKey]) => featureKey),
        );
        const rows = [];
        normalized.split(";").map((entry) => entry.trim()).filter(Boolean).forEach((entry) => {
            const divider = entry.indexOf(":");
            if (divider <= 0) {
                return;
            }
            const featureKey = entry.slice(0, divider).trim();
            const rawValues = entry.slice(divider + 1).trim();
            const filterDef = filtersByFeature.get(featureKey);
            if (!filterDef || !rawValues) {
                return;
            }
            rows.push({
                id: `prefill_${filterDef.id}`,
                filterId: filterDef.id,
                selections: rawValues
                    .split(",")
                    .map((value) => value.trim())
                    .filter(Boolean)
                    .map((value) => ({
                        value,
                        label: value,
                        group: "",
                        record: { value, label: value },
                    })),
            });
        });
        return rows;
    }

