        excludeRows = upsertGroupRow(excludeRows, "excludeComscoreVideoOrCtvBrandSafety", normalizeSelectionEntries(prefill.excludeComscoreVideoOrCtvBrandSafety, ["value"], ["label"]));
        excludeRows = upsertGroupRow(excludeRows, "excludeComscoreVideoOrCtvBrandSuitability", normalizeSelectionEntries(prefill.excludeComscoreVideoOrCtvBrandSuitability, ["value"], ["label"]));
        excludeRows = upsertGroupRow(excludeRows, "excludeDvBrandSafety", normalizeSelectionEntries(prefill.excludeDvBrandSafety, ["value"], ["label"]));
        excludeRows = upsertGroupRow(excludeRows, "excludeDvFraud", normalizeSelectionEntries(prefill.excludeDvFraud, ["value"], ["label"]));

        includeRows = normalizeRowSelectionsForConfig(config, "include", mergeRowsByFilterId([
            ...includeRows,
            ...prefillRowsFromCanonicalTargeting(prefill.targetingIncl, config, "include"),
        ]));
        excludeRows = normalizeRowSelectionsForConfig(config, "exclude", mergeRowsByFilterId([
            ...excludeRows,
            ...prefillRowsFromCanonicalTargeting(prefill.targetingExcl, config, "exclude"),
        ]));

        if (includeRows.length > 0) {
            dynamicGroups.include = includeRows;
        }
        if (excludeRows.length > 0) {
            dynamicGroups.exclude = excludeRows;
        }
        if (scopeRows.length > 0) {
            dynamicGroups.scope = mergeRowsByFilterId(scopeRows);
        }

        next.dynamicGroups = dynamicGroups;
        setScopeState(next, {
            audienceIds: audienceSelections.map((entry) => entry.value),
            adOrderIds: adOrderSelections.map((entry) => entry.value),
            targetKey: prefill?.scope?.targetKey ?? prefill?.scope?.target_key ?? prefill?.targetKey ?? prefill?.target_key,
        });

        const scopeParams = {};
        const prefilledChannelIds = normalizeForecastChannelIds(prefill.includeChannelV2);
        if (prefilledChannelIds.length > 0) {
            scopeParams.channelIds = prefilledChannelIds;
        }

        const start = String(prefill.from || "").trim();
        const end = String(prefill.to || "").trim();
        if (start || end) {
            scopeParams.dateRange = {
                start,
                end,
            };
        }
        writeScopeParamValues(next, scopeParams);

        const finalized = applyForecastHandoff(next, prefill, config);
        applySeededContextPreset(finalized, config, mergeRowsByFilterId(scopeRows));
        return applyReportDefinition(finalized, windowForm?.reportDefinition);
    }

    function buildRequest({ request, state }) {
        const next = clone(request);
        const filters = {
            ...(next.filters || {}),
        };

        [
            "audienceIds",
            "adOrderIds",
            "includeChannelv2",
            "excludeChannelv2",
