            "includeIasKeywordEid",
            "excludeIasKeywordEid",
            "includeAdelaideGrouping",
            "excludeAdelaideGrouping",
            "includeAgegroupId",
            "excludeAgegroupId",
            "includeHouseIncomeId",
            "excludeHouseIncomeId",
            "includeComscoreDemographics",
            "excludeComscoreDemographics",
            "includePeer39Language",
            "excludePeer39Language",
            "includeComscoreLanguage",
            "excludeComscoreLanguage",
            "includeComscoreVideoOrCtvLanguage",
            "excludeComscoreVideoOrCtvLanguage",
            "includePeer39Context",
            "excludePeer39Context",
            "includePeer39Safety",
            "excludePeer39Safety",
            "includePeer39MobileApps",
            "excludePeer39MobileApps",
            "includePeer39Fraud",
            "excludePeer39Fraud",
            "includePeer39Specialty",
            "excludePeer39Specialty",
            "includePeer39Sentiment",
            "excludePeer39Sentiment",
            "includePeer39PageSignals",
            "excludePeer39PageSignals",
            "includePeer39CustomStandard",
            "excludePeer39CustomStandard",
            "includePeer39CustomAdvanced",
            "excludePeer39CustomAdvanced",
            "includePeer39Language",
            "excludePeer39Language",
            "includePeer39SocialPredict",
            "excludePeer39SocialPredict",
            "includePeer39Weather",
