            "includePeer39OttCtv",
            "excludePeer39OttCtv",
            "includeGsContextual",
            "excludeGsContextual",
            "includeComscoreCustom",
            "excludeComscoreCustom",
            "includeComscoreSyndicatedRankings",
            "excludeComscoreSyndicatedRankings",
            "includeIasBrandSafety",
            "excludeIasBrandSafety",
            "includeSupplyPaths",
            "excludeSupplyPaths",
            "includeIasFraud",
            "excludeIasFraud",
            "includeIasTraq",
            "excludeIasTraq",
            "includeIasViewability",
            "excludeIasViewability",
            "includeComscoreBrandSafety",
            "excludeComscoreBrandSafety",
            "includeComscoreBrandSuitability",
            "excludeComscoreBrandSuitability",
            "includeMlViewability",
            "excludeMlViewability",
            "includeDvAuthBs",
            "excludeDvAuthBs",
            "includeDvViewability",
            "excludeDvViewability",
            "excludeDvBrandSafety",
            "excludeDvFraud",
            "includeComscoreVideoOrCtvBrandSafety",
            "excludeComscoreVideoOrCtvBrandSafety",
            "includeComscoreVideoOrCtvBrandSuitability",
            "excludeComscoreVideoOrCtvBrandSuitability",
        ].forEach((key) => {
            if (filters[key] == null) {
                return;
            }
            filters[key] = coerceIntegerArray(filters[key]);
        });

        if (
            Array.isArray(filters.adOrderIds)
            && filters.adOrderIds.length > 0
            && (!Array.isArray(filters.audienceIds) || filters.audienceIds.length === 0)
        ) {
            throw new Error(
                "Select an audience before running Forecasting. Ad orders contain independent audience targeting stacks and cannot be forecast as one aggregate audience.",
            );
        }

        if (Array.isArray(filters.audienceIds) && filters.audienceIds.length > 1) {
            throw new Error(
                "Run one audience at a time. Multiple audience forecasts cannot be combined because their reachable populations can overlap.",
            );
        }

        [
            "includeDeviceType",
            "excludeDeviceType",
        ].forEach((key) => {
            if (!Array.isArray(filters[key])) {
                return;
            }
            filters[key] = filters[key].map((entry) => normalizeDeviceTypeCode(entry)).filter(Boolean);
        });

        const hasAuthoredDocument = Array.isArray(state?.reportDocumentBlocks) && state.reportDocumentBlocks.length > 0;
        // ForecastingCube executes one day at a time for the live builder
        // surface. Authored dashboard-document preview/export keeps the
        // canonical date range so each dataset can preserve its own scoped
        // request shape through save/reopen/export.
        if (!hasAuthoredDocument) {
            const effectiveDate = String(filters.to || filters.from || filters.date || "").trim();
            if (effectiveDate) {
                filters.date = effectiveDate;
            }
            delete filters.from;
            delete filters.to;
        } else {
            delete filters.date;
        }

        dropEmptyFilterArrays(filters);
        next.filters = filters;
        return next;
    }

    return {
        stewardForecastingBuilder: {
            initializeState,
            buildRequest,
            resolveLookup,
        },
    };
})()
))()
